int rawType()
{
    static_assert((sizeof(_Tp) <= 512), "sizeof(_Tp) is too large" " " "sizeof(_Tp) <= CV_CN_MAX");
    const int elemSize = sizeof(_Tp);
    return (int)(((0) & ((1 << 3) - 1)) + (((elemSize)-1) << 3));
}



