class UniqueRandom
{
    std::vector<int> vals_;
    int size_;
    int counter_;

public:





    UniqueRandom(int n)
    {
        init(n);
    }





    void init(int n)
    {

        vals_.resize(n);
        size_ = n;
        for (int i = 0; i < size_; ++i) vals_[i] = i;



        cv::randShuffle(vals_);




        counter_ = 0;
    }






    int next()
    {
        if (counter_ == size_) {
            return -1;
        }
        else {
            return vals_[counter_++];
        }
    }
};

