namespace cvflann
{






class StartStopTimer
{
    int64 startTime;

public:



    double value;





    StartStopTimer()
    {
        reset();
    }




    void start()
    {
        startTime = cv::getTickCount();
    }




    void stop()
    {
        int64 stopTime = cv::getTickCount();
        value += ( (double)stopTime - startTime) / cv::getTickFrequency();
    }




    void reset()
    {
        value = 0;
    }

};

}
